import org.mockito.Mockito.*
import static org.hamcrest.MatcherAssert.assertThat;
import static org.hamcrest.Matchers.*;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.util.HashMap;
import java.util.Map;
import java.util.Map.Entry;
import org.apache.commons.compress.archivers.ArchiveEntry;
import org.apache.commons.compress.archivers.ArchiveInputStream;
import org.apache.commons.compress.utils.ArchiveUtils;

public class TarArchiveInputStreamTest{
@Rule
    public ExpectedException thrown = ExpectedException.none();

    private TarArchiveInputStream tarArchiveInputStream;

    @Before
    public void setup() throws IOException {
        InputStream is = getClass().getResourceAsStream("/test.tar");
        tarArchiveInputStream = new TarArchiveInputStream(is);
    }

    @After
    public void tearDown() throws IOException {
        tarArchiveInputStream.close();
    }

    @Test
    public void testGetNextTarEntry() throws Exception {
        TarArchiveEntry entry = tarArchiveInputStream.getNextTarEntry();
        assertThat(entry, notNullValue());
    }

    @Test
    public void testGetNextTarEntry_EOF() throws Exception {
        // Simulate hitting EOF
        tarArchiveInputStream.hasHitEOF = true;
        TarArchiveEntry entry = tarArchiveInputStream.getNextTarEntry();
        assertThat(entry, nullValue());
    }

    @Test
    public void testGetNextTarEntry_Skip() throws Exception {
        TarArchiveEntry entry = tarArchiveInputStream.getNextTarEntry();
        long originalSize = entry.getSize();
        long skipped = tarArchiveInputStream.skip(originalSize);
        assertThat(skipped, equalTo(originalSize));
        TarArchiveEntry nextEntry = tarArchiveInputStream.getNextTarEntry();
        assertThat(nextEntry, notNullValue());
    }

    @Test
    public void testGetNextTarEntry_ParseHeader() throws Exception {
        TarArchiveEntry entry = tarArchiveInputStream.getNextTarEntry();
        assertThat(entry.getName(), notNullValue());
    }

    @Test
    public void testGetNextTarEntry_PaxHeaders() throws Exception {
        TarArchiveEntry entry = tarArchiveInputStream.getNextTarEntry();
        if (entry.isPaxHeader()) {
            Map<String, String> paxHeaders = tarArchiveInputStream.parsePaxHeaders(new InputStreamReader(tarArchiveInputStream));
            assertThat(paxHeaders, notNullValue());
        }
    }

    @Test
    public void testGetNextTarEntry_GNUlongName() throws Exception {
        TarArchiveEntry entry = tarArchiveInputStream.getNextTarEntry();
        if (entry.isGNULongNameEntry()) {
            String longName = "";
            int length = 0;
            byte[] buf = new byte[256];
            while ((length = tarArchiveInputStream.read(buf)) >= 0) {
                longName += new String(buf, 0, length);
            }
            assertThat(longName, notNullValue());
        }
    }

    @Test
    public void testGetNextTarEntry_GNUSparse() throws Exception {
        TarArchiveEntry entry = tarArchiveInputStream.getNextTarEntry();
        if (entry.isGNUSparse()) {
            tarArchiveInputStream.readGNUSparse();
            assertThat(entry.getSize(), greaterThan(0L));
        }
    }

    @Test
    public void testGetNextTarEntry_Malformed() throws Exception {
        // Simulate a malformed tar file
        TarArchiveEntry entry = tarArchiveInputStream.getNextTarEntry();
        tarArchiveInputStream.currEntry = null;
        thrown.expect(IOException.class);
        tarArchiveInputStream.getNextTarEntry();
    }
}
